def trails(repo):
    seen = {}
    for status in ["open", "closed"]:
        rc, out, err = run(["trail", "list", "--project", PROJECT, "--repo", f"{PROJECT}/{repo}",
                            "--status", status, "--limit", "100", "--json"])
        save(f"{OUT}/trails/{repo}-{status}.json", out)
        if rc:
            log(f"trail list {repo} {status} rc={rc} {err[:200]}")
            continue
        d = json.loads(out)
        log(f"trails {repo} {status}: items={len(d.get('items', []))} token={d.get('nextPageToken')}")
        for it in d.get("items", []):
            seen[it["number"]] = it
    changes = {}
    for num in sorted(seen):
        rc, out, err = run(["trail", "show", str(num), "--project", PROJECT, "--repo", f"{PROJECT}/{repo}", "--json"])
        save(f"{OUT}/trail-show/{repo}/{num}.json", out if rc == 0 else f"ERROR rc={rc}\n{err}")
        if rc:
            log(f"trail show {repo} {num} rc={rc}")
            continue
        for ch in json.loads(out).get("changes", []):
            changes[(ch.get("repository", repo), ch["number"])] = repo
    log(f"changes {repo}: {len(changes)} from {len(seen)} trails")
    return [(repo, n, rname) for (rname, n), repo in sorted(changes.items())]

