"""Re-pull findings for every change in all three statuses."""
import json
import os
import subprocess
from concurrent.futures import ThreadPoolExecutor

CWD = "/Users/gabe/Projects/wisp-plugins/.claude/worktrees/review-slop-evaluation"
H = "/Users/gabe/.claude/jobs/45cd44b5/tmp/harvest"
changes = set()
for repo in ["caliper", "callisto"]:
    d = f"{H}/trail-show/{repo}"
    for f in os.listdir(d):
        t = open(f"{d}/{f}").read()
        if t.startswith("ERROR"):
            continue
        for ch in json.loads(t).get("changes", []):
            changes.add((repo, ch.get("repository", repo), ch["number"]))


def pull(item):
    repo, rname, n = item
    out_all = {}
    for st in ["open", "resolved", "dismissed"]:
        p = subprocess.run(["entire", "trail", "finding", "list", f"{rname}/{n}", "--project", "gh/orin-dx",
                            "--freshness", "any", "--status", st, "--json"], cwd=CWD, capture_output=True, text=True)
        if p.returncode:
            out_all[st] = {"error": p.stderr.strip()[-200:]}
        else:
            out_all[st] = json.loads(p.stdout)
    os.makedirs(f"{H}/findings-all/{repo}", exist_ok=True)
    with open(f"{H}/findings-all/{repo}/{rname}-{n}.json", "w") as fh:
        json.dump(out_all, fh, indent=1)
    return item, {st: len(v.get("findings", [])) for st, v in out_all.items()}, any("error" in v for v in out_all.values())


with ThreadPoolExecutor(4) as ex:
    results = list(ex.map(pull, sorted(changes)))
tot = {"open": 0, "resolved": 0, "dismissed": 0}
errs = 0
by_repo = {}
for (repo, rname, n), counts, err in results:
    errs += err
    for k, v in counts.items():
        tot[k] += v
        by_repo.setdefault(repo, {}).setdefault(k, 0)
        by_repo[repo][k] += v
    if sum(counts.values()):
        print(repo, f"{rname}/{n}", counts)
print("changes", len(results), "errors", errs, "totals", tot, by_repo)

